"""Generate native constants from the public component-level boot contract."""
from pathlib import Path
import argparse,json

ROOT=Path(__file__).resolve().parents[2]
SOURCE=ROOT/'magisk-mali-global/contracts/boot-firmware.json'
TARGET=ROOT/'magisk-mali-global/src/cold_firmware_contract.h'

def render():
    c=json.loads(SOURCE.read_text(encoding='utf-8'))
    quote=lambda value:json.dumps(value,ensure_ascii=True)
    rows=['// SPDX-License-Identifier: MIT',
          '// Generated by tools/cold-boot/generate_contract.py; do not edit.',
          '#ifndef RK_COLD_FIRMWARE_CONTRACT_H','#define RK_COLD_FIRMWARE_CONTRACT_H',
          '#define RK_BOOT_BYTES '+str(c['partition_bytes'])+'ULL',
          '#define RK_BOOT_FIXED_HEADER '+quote(c['fixed_header_sha256']),
          '#define RK_BOOT_BASE_CMD '+quote(c['cmdline']),
          '#define RK_BOOT_BLACKLIST "initcall_blacklist=kbase_platform_driver_init"',
          'static const char *const rk_boot_extra_cmd[]={'+','.join(map(quote,c['allowed_extra_cmdline']))+'};']
    rows+=['#define RK_BOOT_PART_'+str(i)+'_BYTES '+str(c['parts'][str(i)]['bytes'])+'U\n'+
           '#define RK_BOOT_PART_'+str(i)+'_SHA '+quote(c['parts'][str(i)]['sha256']) for i in (0,2,3,4)]
    return '\n'.join(rows+['#endif',''])

if __name__=='__main__':
    p=argparse.ArgumentParser(description=__doc__);p.add_argument('--check',action='store_true');a=p.parse_args()
    text=render()
    if a.check:
        if not TARGET.is_file() or TARGET.read_text(encoding='utf-8')!=text:
            raise SystemExit('Native firmware constants differ; regenerate them')
    else:
        TARGET.write_text(text,encoding='utf-8',newline='\n')
